	const ordered =
		names.length === 3 &&
		names[0] === "Summary" &&
		names[1] === "Changes" &&
		names[2] === "Testing";
	const preamble = text.slice(0, spans[0]?.headingStart ?? text.length).trim();
	const out: Sections = { ordered, preamble };
	const s = body("Summary");
	const c = body("Changes");
	const t = body("Testing");
	if (s) out.summary = s;
	if (c) out.changes = c;
	if (t) out.testing = t;
	return out;
}

